import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
s = data[1]

prefix_sums = {0: -1}
balance = 0
max_length = 0

for i in range(n):
    if s[i] == '0':
        balance -= 1
    else:
        balance += 1

    if balance in prefix_sums:
        max_length = max(max_length, i - prefix_sums[balance])
    else:
        prefix_sums[balance] = i

print(max_length)

